Here is a clean Template Method implementation in Python. The template defines the sorting skeleton and the primitive operations `compare` and `swap` are reused by the concrete algorithms.

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    # Template Method - final skeleton
    def sort(self):
        self._preprocess()
        self._do_sort()
        self._postprocess()
        return self.data

    def _preprocess(self):
        pass

    def _postprocess(self):
        pass

    # Primitive operations
    def compare(self, i, j):
        return self.data[i] > self.data[j]

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    @abstractmethod
    def _do_sort(self):
        pass


class BubbleSort(SortAlgorithm):
    def _do_sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(j, j + 1):
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def _do_sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.data[j] < self.data[min_idx]:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    nums = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry"]

    bubble_nums = BubbleSort(nums).sort()
    select_nums = SelectionSort(nums).sort()

    bubble_strs = BubbleSort(strs).sort()
    select_strs = SelectionSort(strs).sort()

    print("BubbleSort nums:", bubble_nums)
    print("SelectionSort nums:", select_nums)
    print("BubbleSort strs:", bubble_strs)
    print("SelectionSort strs:", select_strs)
```

`SortAlgorithm.sort` is the template method. `BubbleSort` and `SelectionSort` provide their own `_do_sort` algorithm while reusing the common `compare` and `swap` primitives defined in the base class.
